CREATE TABLE IF NOT EXISTS staff_permissions(staff_id BIGINT UNSIGNED PRIMARY KEY,permissions JSON NOT NULL);
CREATE TABLE IF NOT EXISTS clinics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,address TEXT NOT NULL,phone VARCHAR(30) NOT NULL DEFAULT '',active TINYINT NOT NULL DEFAULT 1);
INSERT INTO clinics(id,name,address) SELECT 1,COALESCE((SELECT value FROM settings WHERE `key`='name'),'مدیریت کلینیک مسیحا'),'' WHERE NOT EXISTS(SELECT 1 FROM clinics WHERE id=1);
CREATE TABLE IF NOT EXISTS labels(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,color VARCHAR(7) NOT NULL DEFAULT '#087f75',active TINYINT NOT NULL DEFAULT 1,is_default TINYINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS service_categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS service_staff(service_id BIGINT UNSIGNED NOT NULL,staff_id BIGINT UNSIGNED NOT NULL,share_type ENUM('fixed','percent') NOT NULL DEFAULT 'percent',share_value DECIMAL(14,2) NOT NULL DEFAULT 0,PRIMARY KEY(service_id,staff_id));
CREATE TABLE IF NOT EXISTS packages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,price BIGINT UNSIGNED NOT NULL DEFAULT 0,auto_price TINYINT NOT NULL DEFAULT 1,active TINYINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS package_items(package_id BIGINT UNSIGNED NOT NULL,service_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL DEFAULT 1,PRIMARY KEY(package_id,service_id));
CREATE TABLE IF NOT EXISTS clinic_forms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pid BIGINT NOT NULL,title VARCHAR(160) NOT NULL,kind ENUM('visit','general') NOT NULL,body TEXT NOT NULL,created_by BIGINT NOT NULL,deleted TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS referral_fees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,episode_id BIGINT UNSIGNED NOT NULL,recipient VARCHAR(160) NOT NULL,kind ENUM('fixed','percent') NOT NULL,value DECIMAL(14,2) NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS custom_fonts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,filename VARCHAR(80) NOT NULL,format VARCHAR(10) NOT NULL);
ALTER TABLE patients ADD COLUMN IF NOT EXISTS created_by BIGINT NOT NULL DEFAULT 0;
ALTER TABLE patients ADD COLUMN IF NOT EXISTS label_id BIGINT UNSIGNED NULL;
ALTER TABLE staff ADD COLUMN IF NOT EXISTS deleted TINYINT NOT NULL DEFAULT 0;
ALTER TABLE services ADD COLUMN IF NOT EXISTS category_id BIGINT UNSIGNED NULL;
ALTER TABLE services ADD COLUMN IF NOT EXISTS deleted TINYINT NOT NULL DEFAULT 0;
ALTER TABLE packages ADD COLUMN IF NOT EXISTS deleted TINYINT NOT NULL DEFAULT 0;
ALTER TABLE service_categories ADD COLUMN IF NOT EXISTS deleted TINYINT NOT NULL DEFAULT 0;
ALTER TABLE labels ADD COLUMN IF NOT EXISTS deleted TINYINT NOT NULL DEFAULT 0;
ALTER TABLE physio_sessions ADD COLUMN IF NOT EXISTS label_id BIGINT UNSIGNED NULL;
ALTER TABLE physio_sessions ADD COLUMN IF NOT EXISTS clinic_id BIGINT UNSIGNED NOT NULL DEFAULT 1;
ALTER TABLE physio_sessions ADD COLUMN IF NOT EXISTS service_id BIGINT UNSIGNED NULL;
ALTER TABLE physio_sessions ADD COLUMN IF NOT EXISTS price_snapshot BIGINT UNSIGNED NOT NULL DEFAULT 0;
ALTER TABLE physio_sessions ADD COLUMN IF NOT EXISTS share_snapshot DECIMAL(14,2) NOT NULL DEFAULT 0;
ALTER TABLE physio_payments ADD COLUMN IF NOT EXISTS voided TINYINT NOT NULL DEFAULT 0;
ALTER TABLE physio_payments ADD COLUMN IF NOT EXISTS change_reason VARCHAR(255) NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS financial_changes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,payment_id BIGINT UNSIGNED NOT NULL,old_amount BIGINT NOT NULL,new_amount BIGINT NOT NULL,reason VARCHAR(255) NOT NULL,actor BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
